/* ==================================================================
   WAVE FOUR: THE HOME SERVICES MARKET, 18 AUGUST 2026.

   One hundred and eighteen rows added for the Champions West console:
   seven Champions Group brand locations and one hundred and eleven
   competing operators across Orange, Los Angeles, San Bernardino,
   Riverside, San Diego and Ventura counties. Every row above this
   banner is one of the three hundred and twenty nine local organisations this
   console inherited, re-read as a PARTNER rather than as a buyer:
   schools, employers, civic bodies and referral businesses are the
   sponsorship and hyper-local surfaces a division marketer works, not
   people who buy a furnace.

   HOW THEY WERE GATHERED, AND WHAT WAS THROWN AWAY.
   Six researchers worked one county and service line each, reading each
   operator's own website rather than a directory. A seventh pass then
   tried to break every row: it found a franchise researched off the
   wrong page with four wrong fields, a company recorded in the wrong
   city, three offers paraphrased rather than quoted, and two founding
   years the operator's own pages contradict. Those are fixed.

   THE RATINGS ARE DELIBERATELY EMPTY, AND THAT IS THE FINDING.
   Thirteen rows arrived carrying a Google rating and a review count and
   the verification pass could confirm almost none of them, because the
   number on a contractor's homepage is nearly always a self-hosted
   widget blending Google, Yelp, Facebook and Angi, months stale. One
   operator publishes a "Google" count of 5,137 that no platform shows;
   another publishes 3,000+ where Yelp lists 510. So the platform fields
   are blank on every row but the one that could be read on the platform
   itself. A reputation column full of numbers nobody can check is worse
   than an empty one.

   EVERY COORDINATE IS AN EXACT STREET MATCH FROM THE US CENSUS BUREAU.
   One hundred and twenty five addresses went to the geocoder and one
   hundred and eleven came back with the street number, the directional
   and the street name all agreeing with the request. Fourteen did not
   and carry no pin at all, because this geocoder answers 200 with a
   confident substitution: it offered W Valley Blvd for E Valley Blvd,
   S Lakeview for N Lakeview and N Raymond for S Raymond, each a point
   on the wrong side of a real city. A missing pin is a gap. A wrong pin
   on a real company's building is a liability.
   ================================================================== */
