export const PROSPECT_BY_ID: Record<string, Prospect> = Object.fromEntries(
  PROSPECTS.map((p) => [p.id, p]),
);

/** Organisations that publish an email we actually read off their site. */
export const EMAILABLE = PROSPECTS.filter(
  (p) => p.emailConfidence === "verified_public",
);

/**
 * Organisations with no written door at all.
 *
 * This is not a leftover list. It is the go-see route, and it is sorted
 * by distance from the venue on the field board for exactly that reason.
 */
export const DOOR_ONLY = PROSPECTS.filter((p) => p.emailConfidence === "none");

/**
 * RESEARCHED, FOUND REAL, AND NOT ON THE BOARD.
 *
 * Twenty five organisations that are on nobody's map here, and the reason
 * for each. Fifteen of them the US Census geocoder could not match at
 * all, which is a statement about the Census address file rather than
 * about the business: its ranges lag new construction, which is why the
 * Village at La Floresta and the newer Imperial Highway centres failed
 * while every older Brea Boulevard address matched first time. Eight are
 * worse than that, and more interesting: the geocoder came back with a
 * DIFFERENT STREET from the one the research pass had read, which is
 * exactly the disagreement that took Round One Entertainment off this
 * file. The last two are real and have nothing loadable behind them that
 * proves the address or that they still trade.
 *
 * The alternative was to nudge a nearby pin, and that is the one thing
 * that would discredit the other three hundred and twenty nine. An unmatched row
 * is a fact somebody can act on. A fabricated pin is not.
 *
 * The Method page renders this list, so the removal is visible rather
 * than silent.
 */
/**
 * WHY A REMOVAL CARRIES ITS OWN KIND.
 *
 * The Method page groups these, because the two groups make completely
 * different arguments: an address the Census file has never heard of says
 * something about the Census file, and an address two sources disagree
 * about says something about the address. It used to work out which was
 * which by matching the organisation's NAME against a list of two
 * hard-coded strings, which was fine for nine rows and silently wrong for
 * twenty five.
 *
 * So the row says what kind of removal it is, and the screen groups on
 * that rather than guessing from prose it does not control.
 */
export type ExclusionKind =
  /** The geocoder holds no address range for the number. A TIGER gap. */
  | "unmatched"
  /** Two sources name different streets. Nobody has established this yet. */
  | "disagreement"
  /** Real, but nothing loadable proves the address or that it still trades. */
  | "unverifiable";

